import React from 'react';
import { MiniUpgradeCard } from './MiniUpgradeCard';
import { UPGRADES } from '../../game/upgrades';

// Component to display mini upgrade cards at the bottom of the screen
export const MiniUpgradeCardsDisplay = ({ playerStats, cooldowns }: {
  playerStats: any;
  cooldowns?: { lavaShot?: number; iceShard?: number; };
}) => {
  if (!playerStats.upgrades || Object.keys(playerStats.upgrades).length === 0) {
    return null;
  }

  const upgradeEntries = Object.entries(playerStats.upgrades as Record<string, number>);

  return (
    <div style={{
      position: 'fixed',
      bottom: 15,
      left: '50%',
      transform: 'translateX(-50%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '6px',
      zIndex: 2000,
      background: 'rgba(0,0,0,0.3)',
      borderRadius: '10px',
      padding: '9px',
      backdropFilter: 'blur(8px)',
      border: '1px solid rgba(255,255,255,0.1)'
    }}>
      {upgradeEntries.map(([upgradeName, level]) => {
        const upgrade = UPGRADES.find(u => u.name === upgradeName);
        if (!upgrade) return null;

        // Get cooldown for this specific upgrade
        let cooldown: number | undefined;
        if (upgradeName === 'Lava Shot' && cooldowns?.lavaShot !== undefined) {
          cooldown = cooldowns.lavaShot;
        } else if (upgradeName === 'Ice Shard' && cooldowns?.iceShard !== undefined) {
          cooldown = cooldowns.iceShard;
        }

        return (
          <MiniUpgradeCard
            key={upgradeName}
            upgrade={upgrade}
            level={level}
            cooldown={cooldown} />
        );
      })}
    </div>
  );
};
