import React, { useState, useRef, useEffect } from 'react';

export interface ScrollBarProps {
  children: React.ReactNode;
  height?: string | number;
  width?: string | number;
  fullWidth?: boolean;
  scrollBarWidth?: number;
  scrollBarColor?: string;
  scrollBarTrackColor?: string;
  className?: string;
  style?: React.CSSProperties;
}

export const ScrollBar: React.FC<ScrollBarProps> = ({
  children,
  height = '300px',
  width = '100%',
  fullWidth = false,
  scrollBarWidth = 12,
  scrollBarColor = '#9a9a9a',
  scrollBarTrackColor = '#7a7a7a',
  className = '',
  style = {},
}) => {
  const [scrollTop, setScrollTop] = useState(0);
  const [scrollHeight, setScrollHeight] = useState(0);
  const [clientHeight, setClientHeight] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [dragStartY, setDragStartY] = useState(0);
  const [dragStartScrollTop, setDragStartScrollTop] = useState(0);
  
  const containerRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  const scrollBarRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const updateScrollInfo = () => {
      if (contentRef.current) {
        setScrollHeight(contentRef.current.scrollHeight);
        setClientHeight(contentRef.current.clientHeight);
        setScrollTop(contentRef.current.scrollTop);
      }
    };

    updateScrollInfo();
    window.addEventListener('resize', updateScrollInfo);
    
    const contentElement = contentRef.current;
    if (contentElement) {
      contentElement.addEventListener('scroll', updateScrollInfo);
    }

    return () => {
      window.removeEventListener('resize', updateScrollInfo);
      if (contentElement) {
        contentElement.removeEventListener('scroll', updateScrollInfo);
      }
    };
  }, []);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  };

  const handleScrollBarClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current || !contentRef.current) return;
    
    const rect = containerRef.current.getBoundingClientRect();
    const clickY = e.clientY - rect.top;
    const scrollBarHeight = rect.height;
    const scrollRatio = clickY / scrollBarHeight;
    const newScrollTop = scrollRatio * (scrollHeight - clientHeight);
    
    contentRef.current.scrollTop = newScrollTop;
  };

  const handleScrollBarMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
    e.preventDefault();
    setIsDragging(true);
    setDragStartY(e.clientY);
    setDragStartScrollTop(scrollTop);
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging || !containerRef.current || !contentRef.current) return;
      
      const deltaY = e.clientY - dragStartY;
      const rect = containerRef.current.getBoundingClientRect();
      const scrollBarHeight = rect.height;
      const scrollRatio = deltaY / scrollBarHeight;
      const newScrollTop = dragStartScrollTop + (scrollRatio * (scrollHeight - clientHeight));
      
      contentRef.current.scrollTop = Math.max(0, Math.min(newScrollTop, scrollHeight - clientHeight));
    };

    const handleMouseUp = () => {
      setIsDragging(false);
    };

    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, dragStartY, dragStartScrollTop, scrollHeight, clientHeight]);

  const scrollBarHeight = clientHeight > 0 ? (clientHeight / scrollHeight) * clientHeight : 0;
  const scrollBarTop = scrollHeight > clientHeight ? (scrollTop / (scrollHeight - clientHeight)) * (clientHeight - scrollBarHeight) : 0;

  const containerStyle: React.CSSProperties = {
    position: 'relative',
    width: fullWidth ? '100%' : width,
    height,
    display: 'flex',
    ...style,
  };

  const contentStyle: React.CSSProperties = {
    flex: 1,
    overflow: 'auto',
    scrollbarWidth: 'none',
    msOverflowStyle: 'none',
  };

  const scrollBarTrackStyle: React.CSSProperties = {
    position: 'absolute',
    right: 0,
    top: 0,
    width: scrollBarWidth,
    height: '100%',
    backgroundColor: scrollBarTrackColor,
    cursor: 'pointer',
  };

  const scrollBarStyle: React.CSSProperties = {
    position: 'absolute',
    right: 0,
    top: scrollBarTop,
    width: scrollBarWidth,
    height: scrollBarHeight,
    backgroundColor: scrollBarColor,
    cursor: isDragging ? 'grabbing' : 'grab',
    transition: isDragging ? 'none' : 'background-color 0.2s ease',
  };

  return (
    <div
      ref={containerRef}
      className={`ui-scrollbar ${className}`}
      style={containerStyle}
    >
      <div
        ref={contentRef}
        className="ui-scrollbar-content"
        style={contentStyle}
        onScroll={handleScroll}
      >
        {children}
      </div>
      {scrollHeight > clientHeight && (
        <>
          <div
            className="ui-scrollbar-track"
            style={scrollBarTrackStyle}
            onClick={handleScrollBarClick}
          />
          <div
            ref={scrollBarRef}
            className="ui-scrollbar-thumb"
            style={scrollBarStyle}
            onMouseDown={handleScrollBarMouseDown}
          />
        </>
      )}
    </div>
  );
};
