import React, { useState, useRef, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { UPGRADE_COLORS } from '../../game/upgrades';

// Custom tooltip component that renders outside the container with formatted content

export const MiniTooltip = ({ content, children, upgrade }: { content: string; children: React.ReactNode; upgrade?: any; }) => {
  const [isVisible, setIsVisible] = useState(false);
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const triggerRef = useRef<HTMLDivElement>(null);

  const showTooltip = () => {
    timeoutRef.current = setTimeout(() => {
      if (triggerRef.current) {
        const rect = triggerRef.current.getBoundingClientRect();
        setPosition({
          x: rect.left + rect.width / 2,
          y: rect.top - 60
        });
      }
      setIsVisible(true);
    }, 500);
  };

  const hideTooltip = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    setIsVisible(false);
  };

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  // Parse content to handle the separator line
  const renderFormattedContent = () => {
    if (!content) return null;

    const parts = content.split('\n\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n');
    if (parts.length === 1) {
      // No separator, just render as plain text
      return <div style={{ whiteSpace: 'pre-wrap', lineHeight: '1.4' }}>{content}</div>;
    }

    return (
      <div style={{ whiteSpace: 'pre-wrap', lineHeight: '1.4' }}>
        <div style={{ marginBottom: '8px' }}>{parts[0]}</div>
        <div style={{
          height: '1px',
          background: 'linear-gradient(90deg, transparent, #666, transparent)',
          margin: '8px 0',
          opacity: 0.6
        }} />
        <div style={{ color: '#ccc', fontSize: '11px' }}>{parts[1]}</div>
      </div>
    );
  };

  // Render tooltip header with title and category
  const renderTooltipHeader = () => {
    if (!upgrade) return null;

    return (
      <div style={{ marginBottom: '12px' }}>
        {/* Title */}
        <div style={{
          fontSize: '14px',
          fontWeight: 'bold',
          color: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
          marginBottom: '6px',
          textAlign: 'center'
        }}>
          {upgrade.name}
        </div>
        {/* Category tag */}
        <div style={{
          fontSize: '10px',
          fontWeight: '700',
          background: UPGRADE_COLORS[upgrade.category as keyof typeof UPGRADE_COLORS],
          color: '#111',
          borderRadius: '3px',
          padding: '2px 6px',
          display: 'block',
          boxShadow: '0 1px 3px #0002',
          border: '1px solid #fff2',
          textAlign: 'center',
          width: 'fit-content',
          margin: '0 auto'
        }}>
          {upgrade.category}
        </div>
      </div>
    );
  };

  return (
    <>
      <div
        ref={triggerRef}
        onMouseEnter={showTooltip}
        onMouseLeave={hideTooltip}
        style={{ display: 'inline-block' }}
      >
        {children}
      </div>
      {isVisible && createPortal(
        <div
          style={{
            position: 'fixed',
            left: position.x,
            top: position.y,
            transform: 'translateX(-50%) translateY(-100%)',
            background: '#1f1f1f',
            color: '#ffffff',
            padding: '12px 16px',
            borderRadius: '6px',
            fontSize: '12px',
            fontWeight: 'normal',
            letterSpacing: '0.3px',
            whiteSpace: 'normal',
            zIndex: 9999,
            pointerEvents: 'none',
            opacity: 0.95,
            boxShadow: '0 4px 12px rgba(0,0,0,0.7)',
            border: '1px solid rgba(255,255,255,0.3)',
            maxWidth: '280px',
            minWidth: '200px'
          }}
        >
          {renderTooltipHeader()}
          {renderFormattedContent()}
          <div
            style={{
              position: 'absolute',
              top: '100%',
              left: '50%',
              transform: 'translateX(-50%)',
              width: 0,
              height: 0,
              borderLeft: '6px solid transparent',
              borderRight: '6px solid transparent',
              borderTop: '6px solid #1f1f1f'
            }} />
        </div>,
        document.body
      )}
    </>
  );
};
