import { Segment } from "./Segment";
import { BehaviorManager } from "../behaviours/BehaviorManager";
import { SMotionBehavior } from "../behaviours/SMotionBehavior";
import { ChaseBehavior } from "../behaviours/ChaseBehavior";
import { SegmentedEntity } from "./SegmentedEntity";

// Earth Worm enemy - thin segmented enemy that slithers through the earth

export class EarthWormEnemy extends SegmentedEntity {
  behaviorManager: BehaviorManager;

  constructor(
    hp: number,
    armor: number,
    moveSpeed: number,
    attackDamage: number,
    attackSpeed: number,
    attackRange: number,
    magicResist: number,
    magicPower: number,
    evasion: number,
    xp: number,
    projectileScale: number,
    projectileSpeed: number
  ) {
    const segmentRadius = 12; // Thin segments as requested
    const segmentCount = 12; // 12 segments total
    const segmentColor = 0x8b4513; // Brown color

    super(
      "earth_worm",
      segmentCount,
      segmentRadius,
      segmentColor,
      hp,
      armor,
      moveSpeed,
      attackDamage,
      attackSpeed,
      attackRange,
      magicResist,
      magicPower,
      0, // cooldown
      projectileScale,
      projectileSpeed,
      projectileScale, // projectileScale
      0, // burst fire
      0, // crit chance
      0, // crit level
      0, // lifesteal
      0, // regen
      evasion,
      1, // xp boost
      1, // magnet
      0, // luck
      1 // gold find
    );

    // Initialize behavior manager with chase behavior for better segment cohesion
    this.behaviorManager = new BehaviorManager(
      new ChaseBehavior(this.attackRange, this.moveSpeed)
    );
  }

  // Override to create a brown gradient from dark brown head to lighter brown tail
  initializeSegments(scene: any, startX: number, startY: number) {
    // Clear any existing segments first
    this.segments = [];
    this.master = null;

    // Create initial path history - a straight line behind the start position
    this.pathHistory = [];
    const currentTime = scene.time.now;

    // Calculate cumulative spacing for each segment
    let cumulativeSpacing = 0;
    const segmentSpacings: number[] = [];

    for (let i = 0; i < this.segmentCount; i++) {
      if (i === 0) {
        // First segment (head) has no spacing
        segmentSpacings.push(0);
      } else {
        // Each subsequent segment uses spacing based on previous segment's radius
        const spacing = this.getSegmentSpacing(i - 1);
        cumulativeSpacing += spacing;
        segmentSpacings.push(cumulativeSpacing);
      }
    }

    // Create path points - ensure we have enough for all segments
    // For chase behavior, we need a path point for each segment
    for (let i = 0; i < this.segmentCount; i++) {
      const distanceFromStart = segmentSpacings[i] || 0;
      const pathPoint = {
        x: startX - distanceFromStart, // Go backwards in a straight line
        y: startY,
        time: currentTime - i * 50, // Closer time spacing for better cohesion
      };
      this.pathHistory.push(pathPoint);
    }

    // Create body segments first (drawn behind) with gradient from dark brown to light brown
    for (let i = this.segmentCount - 1; i > 0; i--) {
      // Create gradient from dark brown (0x8b4513) to light brown (0xa0522d)
      const progress = 1 - i / (this.segmentCount - 1); // Inverted: 1 to 0 (dark to light)
      const darkBrown = 0x8b4513;
      const lightBrown = 0xa0522d;

      // Interpolate between dark and light brown
      const r1 = (darkBrown >> 16) & 0xff;
      const g1 = (darkBrown >> 8) & 0xff;
      const b1 = darkBrown & 0xff;

      const r2 = (lightBrown >> 16) & 0xff;
      const g2 = (lightBrown >> 8) & 0xff;
      const b2 = lightBrown & 0xff;

      const r = Math.floor(r1 + (r2 - r1) * progress);
      const g = Math.floor(g1 + (g2 - g1) * progress);
      const b = Math.floor(b1 + (b2 - b1) * progress);

      const segmentColor = (r << 16) | (g << 8) | b;

      // All segments have radius 12 for consistency
      const segmentRadius = 12;

      // Position segment along the initial path
      const pathIndex = Math.max(0, Math.min(this.pathHistory.length - 1, this.pathHistory.length - 1 - i));
      const pathPoint = this.pathHistory[pathIndex];

      const segment = new Segment(
        pathPoint.x,
        pathPoint.y,
        segmentRadius,
        segmentColor,
        false
      );
      segment.setVisible(true);
      this.segments.push(segment);
    }

    // Create master segment (head) last (drawn on top) with dark brown
    const masterRadius = 12; // Same radius as body segments
    const masterSegment = new Segment(
      startX,
      startY,
      masterRadius,
      0x8b4513, // Dark brown head
      true
    );
    this.master = masterSegment;
    this.segments.push(masterSegment);
  }

  // Override getMasterSegment to ensure radius consistency
  getMasterSegment(): Segment | null {
    if (this.master && this.master.radius !== 12) {
      // Force the master segment radius to be 12 if it got changed
      this.master.radius = 12;
    }
    return this.master;
  }
}
