import { ITEMS } from '../game/items';

export class ItemManager {
  private scene: any;
  private itemNotification?: Phaser.GameObjects.Container;
  private healthPotionTimer?: Phaser.Time.TimerEvent;
  private healthPotionActive: boolean = false;
  private healthPotionHealTimer?: Phaser.Time.TimerEvent;

  constructor(scene: any) {
    this.scene = scene;
  }

  /**
   * Gives an item to the player character
   * @param itemName The name of the item to give
   * @returns True if the item was successfully added
   */
  giveItemToPlayer(itemName: string): boolean {
    if (!this.scene.playerCharacter) {
      return false;
    }

    const item = ITEMS.find(i => i.name === itemName);
    if (!item) {
      console.warn(`Item not found: ${itemName}`);
      return false;
    }

    // Check if player has enough gold for non-free items
    if (item.price > 0 && this.scene.playerCharacter.gold < item.price) {
      console.warn(`Not enough gold for ${itemName}. Need ${item.price}, have ${this.scene.playerCharacter.gold}`);
      return false;
    }

    // Add the item
    const success = this.scene.playerCharacter.addItem(itemName, this.scene, item.maxStack);

    if (success) {
      // Deduct gold if it's not free
      if (item.price > 0) {
        this.scene.playerCharacter.gold -= item.price;
      }

      // Show acquisition notification
      this.showItemNotification(itemName, item.icon);

      // Handle special item effects
      this.handleSpecialItemEffects(itemName);

      console.log(`Player acquired item: ${itemName}`);
      return true;
    }

    return false;
  }

  /**
   * Removes an item from the player character
   * @param itemName The name of the item to remove
   * @returns True if the item was successfully removed
   */
  removeItemFromPlayer(itemName: string): boolean {
    if (!this.scene.playerCharacter) {
      return false;
    }

    const success = this.scene.playerCharacter.removeItem(itemName, this.scene);

    if (success) {
      console.log(`Player removed item: ${itemName}`);
    }

    return success;
  }

  /**
   * Shows a notification when an item is acquired
   * @param itemName The name of the item
   * @param icon The icon for the item
   */
  private showItemNotification(itemName: string, icon?: string): void {
    // Remove existing notification if any
    if (this.itemNotification) {
      this.itemNotification.destroy();
    }

    // Create notification container
    this.itemNotification = this.scene.add.container(
      this.scene.cameras.main.centerX,
      this.scene.cameras.main.centerY - 100
    );

    // Background
    const background = this.scene.add.rectangle(0, 0, 300, 80, 0x000000, 0.8);
    background.setStrokeStyle(2, 0xffffff);

    // Icon
    const iconText = this.scene.add.text(-120, -10, icon || '🎒', {
      fontSize: '32px',
      color: '#ffffff'
    });

    // Item name
    const itemText = this.scene.add.text(-60, -15, `Acquired: ${itemName}`, {
      fontSize: '18px',
      color: '#ffffff',
      fontWeight: 'bold'
    });

    // Add to container
    if (this.itemNotification) {
      this.itemNotification.add([background, iconText, itemText]);

      // Animate in
      this.itemNotification.setScale(0.5);
      this.itemNotification.setAlpha(0);
      this.scene.tweens.add({
        targets: this.itemNotification,
        scaleX: 1,
        scaleY: 1,
        alpha: 1,
        duration: 300,
        ease: 'Back.easeOut'
      });
    }

    // Auto-remove after 2 seconds
    this.scene.time.delayedCall(2000, () => {
      if (this.itemNotification) {
        this.scene.tweens.add({
          targets: this.itemNotification,
          scaleX: 0.5,
          scaleY: 0.5,
          alpha: 0,
          duration: 300,
          ease: 'Back.easeIn',
          onComplete: () => {
            if (this.itemNotification) {
              this.itemNotification.destroy();
              this.itemNotification = undefined;
            }
          }
        });
      }
    });
  }

  /**
   * Handles special effects for specific items
   * @param itemName The name of the item
   */
  private handleSpecialItemEffects(itemName: string): void {
    switch (itemName) {
      case 'Health Potion':
        this.startHealthPotion();
        break;
      case 'HE Grenade':
        this.enableHeGrenade();
        break;
      default:
        break;
    }
  }

  /**
   * Starts the Health Potion effect
   */
  private startHealthPotion(): void {
    if (this.healthPotionActive) {
      return; // Already active
    }

    this.healthPotionActive = true;
    let healTicks = 0;
    const maxHealTicks = 40; // 40 ticks = 400 HP over 40 seconds (10 HP/sec)

    // Start healing timer
    this.healthPotionHealTimer = this.scene.time.addEvent({
      delay: 1000, // Heal every second
      callback: () => {
        if (!this.scene.playerCharacter || !this.healthPotionActive) {
          this.stopHealthPotion();
          return;
        }

        // Check if player is below 50% health
        const healthPercentage = this.scene.playerCharacter.hp / this.scene.playerCharacter.maxHp;
        if (healthPercentage < 0.5) {
          // Heal 10 HP
          this.scene.playerCharacter.heal(10);
          healTicks++;

          // Visual effect
          this.showHealEffect();

          // Stop if we've healed the full amount
          if (healTicks >= maxHealTicks) {
            this.stopHealthPotion();
          }
        }
      },
      callbackScope: this,
      loop: true
    });

    console.log('Health Potion activated');
  }

  /**
   * Stops the Health Potion effect
   */
  private stopHealthPotion(): void {
    this.healthPotionActive = false;

    if (this.healthPotionHealTimer) {
      this.healthPotionHealTimer.destroy();
      this.healthPotionHealTimer = undefined;
    }

    console.log('Health Potion deactivated');
  }

  /**
   * Shows a visual healing effect
   */
  private showHealEffect(): void {
    if (!this.scene.player) return;

    // Create healing particles
    for (let i = 0; i < 3; i++) {
      const particle = this.scene.add.circle(
        this.scene.player.x + (Math.random() - 0.5) * 40,
        this.scene.player.y + (Math.random() - 0.5) * 40,
        2,
        0x00ff00,
        0.8
      );

      // Animate particle
      this.scene.tweens.add({
        targets: particle,
        y: particle.y - 20,
        alpha: 0,
        duration: 1000,
        ease: 'Power2',
        onComplete: () => particle.destroy()
      });
    }
  }

  /**
   * Enables HE Grenade functionality for leap attacks
   */
  private enableHeGrenade(): void {
    // The HE Grenade effect is handled in the leap logic in MainScene
    // This method is just for initialization if needed
    console.log('HE Grenade equipped');
  }

  /**
   * Creates a grenade explosion effect
   * @param x X position
   * @param y Y position
   */
  createGrenadeExplosion(x: number, y: number): void {
    // Create explosion effect
    const explosion = this.scene.add.circle(x, y, 10, 0xff6600, 0.8);
    explosion.setStrokeStyle(2, 0xffaa00);

    // Animate explosion
    this.scene.tweens.add({
      targets: explosion,
      scaleX: 4,
      scaleY: 4,
      alpha: 0,
      duration: 500,
      ease: 'Power2',
      onComplete: () => explosion.destroy()
    });

    // Damage enemies in area
    if (this.scene.enemies) {
      const enemies = this.scene.enemies.getChildren() as (Phaser.GameObjects.Arc & { dataObj?: any })[];
      enemies.forEach(enemy => {
        const distance = Phaser.Math.Distance.Between(x, y, enemy.x, enemy.y);
        if (distance <= 120) { // 120px radius
          // Deal 100 damage
          const enemyData = (enemy as any).dataObj;
          if (enemyData && enemyData.character) {
            enemyData.character.takeDamage(100, false);
          }
        }
      });
    }
  }

  /**
   * Sells an item for half its price
   * @param itemName The name of the item to sell
   * @returns True if the item was successfully sold
   */
  sellItem(itemName: string): boolean {
    if (!this.scene.playerCharacter) {
      return false;
    }

    const item = ITEMS.find(i => i.name === itemName);
    if (!item) {
      console.warn(`Item not found for selling: ${itemName}`);
      return false;
    }

    // Check if player has the item
    if (!this.scene.playerCharacter.hasItem(itemName)) {
      console.warn(`Player doesn't have item: ${itemName}`);
      return false;
    }

    // Remove the item
    const removed = this.scene.playerCharacter.removeItem(itemName, this.scene);
    if (!removed) {
      console.warn(`Failed to remove item: ${itemName}`);
      return false;
    }

    // Give player half the price in gold
    const sellPrice = Math.floor(item.price / 2);
    this.scene.playerCharacter.gainGold(sellPrice);

    // Show sell notification
    this.showSellNotification(itemName, sellPrice, item.icon);

    console.log(`Sold ${itemName} for ${sellPrice} gold`);
    return true;
  }

  /**
   * Shows a notification when an item is sold
   * @param itemName The name of the item sold
   * @param goldAmount The amount of gold received
   * @param icon The icon of the item
   */
  private showSellNotification(itemName: string, goldAmount: number, icon?: string): void {
    // Remove existing notification if any
    if (this.itemNotification) {
      this.itemNotification.destroy();
    }

    // Create notification container
    this.itemNotification = this.scene.add.container(
      this.scene.cameras.main.centerX,
      this.scene.cameras.main.centerY - 100
    );

    // Background
    const background = this.scene.add.rectangle(0, 0, 280, 60, 0x000000, 0.8);
    background.setStrokeStyle(2, 0xffffff);

    // Icon
    const iconText = this.scene.add.text(-100, -8, icon || '🎒', {
      fontSize: '24px',
      color: '#ffffff'
    });

    // Sell message
    const sellText = this.scene.add.text(-50, -10, `Sold: ${itemName}`, {
      fontSize: '14px',
      color: '#ffffff',
      fontWeight: 'bold'
    });

    // Gold received
    const goldText = this.scene.add.text(-50, 8, `+${goldAmount} 💰`, {
      fontSize: '12px',
      color: '#ffd700',
      fontWeight: 'bold'
    });

    // Add to container
    if (this.itemNotification) {
      this.itemNotification.add([background, iconText, sellText, goldText]);

      // Animate in
      this.itemNotification.setScale(0.5);
      this.itemNotification.setAlpha(0);
      this.scene.tweens.add({
        targets: this.itemNotification,
        scaleX: 1,
        scaleY: 1,
        alpha: 1,
        duration: 300,
        ease: 'Back.easeOut'
      });
    }

    // Auto-remove after 2 seconds
    this.scene.time.delayedCall(2000, () => {
      if (this.itemNotification) {
        this.scene.tweens.add({
          targets: this.itemNotification,
          scaleX: 0.5,
          scaleY: 0.5,
          alpha: 0,
          duration: 300,
          ease: 'Back.easeIn',
          onComplete: () => {
            if (this.itemNotification) {
              this.itemNotification.destroy();
              this.itemNotification = undefined;
            }
          }
        });
      }
    });
  }

  /**
   * Gets all items owned by the player
   * @returns Array of item names
   */
  getPlayerItems(): string[] {
    return this.scene.playerCharacter?.getItems() || [];
  }

  /**
   * Checks if the player has a specific item
   * @param itemName The name of the item to check
   * @returns True if the player has the item
   */
  playerHasItem(itemName: string): boolean {
    return this.scene.playerCharacter?.hasItem(itemName) || false;
  }

  /**
   * Gets the stack count for a specific item
   * @param itemName The name of the item
   * @returns The stack count
   */
  getItemStack(itemName: string): number {
    return this.scene.playerCharacter?.getItemStack(itemName) || 0;
  }

  /**
   * Updates the ItemManager (called every frame)
   * @param deltaTime Time elapsed since last update
   */
  update(deltaTime: number): void {
    // Update character item cooldowns
    if (this.scene.playerCharacter) {
      this.scene.playerCharacter.updateItemCooldowns(deltaTime);
    }

    // Handle Dual Berettas effect (modify shooting)
    if (this.playerHasItem('Dual Berettas')) {
      this.handleDualBerettas();
    }

    // Handle Echo Stone effect
    if (this.playerHasItem('Echo Stone')) {
      this.handleEchoStone();
    }
  }

  /**
   * Handles Dual Berettas shooting modification
   */
  private handleDualBerettas(): void {
    // This effect is handled in the shooting logic in Character.ts
    // by checking for the dualBerettas property
  }

  /**
   * Handles Echo Stone ability echoing
   */
  private handleEchoStone(): void {
    // This effect is handled in the ability casting logic
    // by checking for the echo property
  }

  /**
   * Destroys the ItemManager and cleans up resources
   */
  destroy(): void {
    this.stopHealthPotion();

    if (this.itemNotification) {
      this.itemNotification.destroy();
      this.itemNotification = undefined;
    }
  }
}
