import React from 'react';

export interface FloatingButtonProps {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: 'primary' | 'secondary' | 'accent' | 'danger';
  size?: 'small' | 'medium' | 'large';
  disabled?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export const FloatingButton: React.FC<FloatingButtonProps> = ({
  children,
  onClick,
  variant = 'primary',
  size = 'medium',
  disabled = false,
  className = '',
  style = {},
}) => {
  const variantStyles = {
    primary: {
      backgroundColor: '#9a9a9a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#aaaaaa' },
      '&:active': { backgroundColor: '#8a8a8a' },
    },
    secondary: {
      backgroundColor: '#7a7a7a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#8a8a8a' },
      '&:active': { backgroundColor: '#6a6a6a' },
    },
    accent: {
      backgroundColor: '#aaaaaa',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#bababa' },
      '&:active': { backgroundColor: '#9a9a9a' },
    },
    danger: {
      backgroundColor: '#8a2a2a',
      color: '#ffffff',
      '&:hover': { backgroundColor: '#9a3a3a' },
      '&:active': { backgroundColor: '#7a1a1a' },
    },
  };

  const sizeStyles = {
    small: { width: '32px', height: '32px', fontSize: '14px' },
    medium: { width: '40px', height: '40px', fontSize: '16px' },
    large: { width: '48px', height: '48px', fontSize: '18px' },
  };

  const baseStyle: React.CSSProperties = {
    ...sizeStyles[size],
    borderRadius: '50%',
    border: 'none',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    cursor: disabled ? 'not-allowed' : 'pointer',
    transition: 'all 0.2s ease',
    boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
    userSelect: 'none',
    ...variantStyles[variant],
    ...style,
  };

  const handleClick = () => {
    if (!disabled && onClick) {
      onClick();
    }
  };

  const handleMouseEnter = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!disabled) {
      const hoverStyle = variantStyles[variant]['&:hover'];
      if (hoverStyle) {
        Object.assign(e.currentTarget.style, hoverStyle);
      }
    }
  };

  const handleMouseLeave = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!disabled) {
      const baseVariantStyle = variantStyles[variant];
      e.currentTarget.style.backgroundColor = baseVariantStyle.backgroundColor as string;
    }
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!disabled) {
      const activeStyle = variantStyles[variant]['&:active'];
      if (activeStyle) {
        Object.assign(e.currentTarget.style, activeStyle);
      }
    }
  };

  const handleMouseUp = (e: React.MouseEvent<HTMLButtonElement>) => {
    if (!disabled) {
      const hoverStyle = variantStyles[variant]['&:hover'];
      if (hoverStyle) {
        Object.assign(e.currentTarget.style, hoverStyle);
      }
    }
  };

  return (
    <button
      className={`ui-floating-button ui-floating-button-${variant} ui-floating-button-${size} ${className}`}
      style={baseStyle}
      onClick={handleClick}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      onMouseDown={handleMouseDown}
      onMouseUp={handleMouseUp}
      disabled={disabled}
    >
      {children}
    </button>
  );
};
