import React from 'react';

export interface ProgressBarProps {
  value: number;
  max?: number;
  min?: number;
  variant?: 'primary' | 'secondary' | 'accent' | 'danger' | 'success';
  size?: 'small' | 'medium' | 'large';
  showLabel?: boolean;
  animated?: boolean;
  fullWidth?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export const ProgressBar: React.FC<ProgressBarProps> = ({
  value,
  max = 100,
  min = 0,
  variant = 'primary',
  size = 'medium',
  showLabel = false,
  animated = true,
  fullWidth = false,
  className = '',
  style = {},
}) => {
  const percentage = Math.min(Math.max(((value - min) / (max - min)) * 100, 0), 100);

  const variantStyles = {
    primary: { backgroundColor: '#9a9a9a' },
    secondary: { backgroundColor: '#7a7a7a' },
    accent: { backgroundColor: '#aaaaaa' },
    danger: { backgroundColor: '#8a2a2a' },
    success: { backgroundColor: '#2a8a2a' },
  };

  const sizeStyles = {
    small: { height: '8px' },
    medium: { height: '12px' },
    large: { height: '16px' },
  };

  const containerStyle: React.CSSProperties = {
    width: fullWidth ? '100%' : '200px',
    backgroundColor: '#5a5a5a',
    position: 'relative',
    overflow: 'hidden',
    ...sizeStyles[size],
    ...style,
  };

  // Check for custom color in style prop
  const customColor = (style as any)['--progress-color'];
  
  const progressStyle: React.CSSProperties = {
    height: '100%',
    width: `${percentage}%`,
    backgroundColor: customColor || variantStyles[variant].backgroundColor,
    transition: animated ? 'width 0.3s ease' : 'none',
    position: 'relative',
    boxShadow: customColor ? `0 0 4px ${customColor}40` : 'none',
  };

  const labelStyle: React.CSSProperties = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    fontSize: size === 'large' ? '12px' : size === 'medium' ? '10px' : '8px',
    fontWeight: 'bold',
    color: '#ffffff',
    textShadow: '1px 1px 2px rgba(0, 0, 0, 0.8)',
    zIndex: 1,
  };

  return (
    <div className={`ui-progress-bar ${className}`} style={containerStyle}>
      <div
        className={`ui-progress-fill ui-progress-${variant}`}
        style={progressStyle}
      />
      {showLabel && (
        <div className="ui-progress-label" style={labelStyle}>
          {Math.round(percentage)}%
        </div>
      )}
    </div>
  );
};
