// Supply tracking system for card rarity
const RARITY_SUPPLY = {
  1: 7,  // Tier 1: 7 total
  2: 5,  // Tier 2: 5 total  
  3: 3   // Tier 3: 3 total
};

// Global supply tracker
let upgradeSupply: Record<string, number> = {};

// Initialize supply for all upgrades
function initializeUpgradeSupply() {
  upgradeSupply = {};
  UPGRADES.forEach(upgrade => {
    upgradeSupply[upgrade.name] = RARITY_SUPPLY[upgrade.rarity as keyof typeof RARITY_SUPPLY];
  });
}

// Reset supply (call this when starting a new game)
function resetUpgradeSupply() {
  initializeUpgradeSupply();
}

export function getRandomUpgrades(count = 3, luckBonus = 0, exclude: string[] = []) {
  // Filter upgrades based on available supply
  const availableUpgrades = UPGRADES.filter(upgrade => 
    upgradeSupply[upgrade.name] > 0 && !exclude.includes(upgrade.name)
  );
  
  const choices = [];
  const maxChoices = count + luckBonus;
  
  while (choices.length < maxChoices && availableUpgrades.length > 0) {
    const idx = Math.floor(Math.random() * availableUpgrades.length);
    const selectedUpgrade = availableUpgrades[idx];
    
    choices.push(selectedUpgrade);
    
    // Remove from available pool to avoid duplicates in this selection
    availableUpgrades.splice(idx, 1);
  }
  
  return choices;
}

// Function to decrease supply when an upgrade is actually selected
function decreaseUpgradeSupply(upgradeName: string) {
  if (upgradeSupply[upgradeName] > 0) {
    upgradeSupply[upgradeName]--;
  }
}

// Debug function to get current supply status
function getUpgradeSupplyStatus() {
  const status: Record<string, { supply: number, rarity: number }> = {};
  UPGRADES.forEach(upgrade => {
    status[upgrade.name] = {
      supply: upgradeSupply[upgrade.name] || 0,
      rarity: upgrade.rarity || 1
    };
  });
  return status;
}


// Helper to convert numbers to Roman numerals
export function toRoman(num: number): string {
  if (num <= 0) return '';
  const romanNumerals = [
    ['M',1000],['CM',900],['D',500],['CD',400],['C',100],['XC',90],['L',50],['XL',40],['X',10],['IX',9],['V',5],['IV',4],['I',1]
  ];
  let result = '';
  for (const [roman, value] of romanNumerals as [string, number][]) {
    while (num >= value) {
      result += roman;
      num -= value;
    }
  }
  return result;
}

