  const countEnemies = (scene: any): EnemyCount[] => {
    if (!scene) return [];
    
    const enemyCounts = new Map<string, { count: number; color: string; type: string; isCurrentStage: boolean }>();
    
    // Get current stage
    let currentStage = null;
    if (scene.gameElapsedTime) {
      const elapsed = Math.floor(scene.gameElapsedTime / 1000);
      currentStage = getCurrentStage(elapsed);
    }
    
    if (!currentStage) return [];
    
    // Initialize all enemies from current stage with count 0
    const allStageEnemies = [
      ...currentStage.normalEnemies,
      ...currentStage.specialEnemies,
      ...currentStage.bossEnemies
    ];
    
    allStageEnemies.forEach(enemyKey => {
      const enemyDef = ENEMY_DEFINITIONS[enemyKey];
      if (enemyDef) {
        const color = `#${enemyDef.color.toString(16).padStart(6, '0')}`;
        enemyCounts.set(enemyKey, {
          count: 0,
          color,
          type: enemyDef.type,
          isCurrentStage: true
        });
      }
    });
    
    // Count active enemies
    if (scene.enemies) {
      const activeEnemies = scene.enemies.getChildren().filter((enemy: any) => enemy.active);
      
      activeEnemies.forEach((enemy: any) => {
        const enemyKey = (enemy as any).enemyKey;
        if (enemyKey) {
          const enemyDef = ENEMY_DEFINITIONS[enemyKey];
          if (enemyDef) {
            const color = `#${enemyDef.color.toString(16).padStart(6, '0')}`;
            
            if (enemyCounts.has(enemyKey)) {
              // This enemy belongs to the current stage
              enemyCounts.get(enemyKey)!.count++;
            } else {
              // This is a leftover enemy from a previous stage
              enemyCounts.set(enemyKey, {
                count: 1,
                color,
                type: enemyDef.type,
                isCurrentStage: false
              });
            }
          }
        }
      });
    }
    
    // Convert to array format and sort by type (Boss, Special, Normal) then by count (highest first)
    return Array.from(enemyCounts.entries())
      .filter(([enemyKey, data]) => data.isCurrentStage) // Only include current stage enemies as individual rows
      .map(([enemyKey, data], index) => ({
        name: enemyKey.replace(/_/g, ' ').replace(/\b\w/g, (l: string) => l.toUpperCase()),
        count: data.count,
        maxCount: 1, // Not used anymore, kept for interface compatibility
        color: data.color,
        isCurrentStage: data.isCurrentStage,
        type: data.type, // Pass the enemy type for icon display
        originalKey: enemyKey, // Keep the original key for sorting
        originalIndex: index // Keep original position for stable sorting
      }))
      .sort((a, b) => {
        // First sort by type: Normal > Special > Boss
        const typeOrder = { 'normal': 0, 'special': 1, 'boss': 2 };
        const aType = ENEMY_DEFINITIONS[a.originalKey]?.type || 'normal';
        const bType = ENEMY_DEFINITIONS[b.originalKey]?.type || 'normal';
        
        if (typeOrder[aType as keyof typeof typeOrder] !== typeOrder[bType as keyof typeof typeOrder]) {
          return typeOrder[aType as keyof typeof typeOrder] - typeOrder[bType as keyof typeof typeOrder];
        }
        
        // Then sort by original position to maintain stable order
        return a.originalIndex - b.originalIndex;
      })
      .map(({ originalKey, originalIndex, ...enemy }) => enemy); // Remove the helper properties from final result
  };

