import React, { useState } from 'react';

export interface InputProps {
  type?: 'text' | 'password' | 'email' | 'number' | 'search';
  placeholder?: string;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  onFocus?: () => void;
  onBlur?: () => void;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  size?: 'small' | 'medium' | 'large';
  fullWidth?: boolean;
  label?: string;
  error?: string;
  className?: string;
  style?: React.CSSProperties;
}

export const Input: React.FC<InputProps> = ({
  type = 'text',
  placeholder,
  value,
  defaultValue,
  onChange,
  onFocus,
  onBlur,
  disabled = false,
  readOnly = false,
  required = false,
  size = 'medium',
  fullWidth = false,
  label,
  error,
  className = '',
  style = {},
}) => {
  const [isFocused, setIsFocused] = useState(false);
  const [internalValue, setInternalValue] = useState(defaultValue || '');

  const currentValue = value !== undefined ? value : internalValue;

  const sizeStyles = {
    small: {
      padding: '6px 8px',
      fontSize: '12px',
      minHeight: '28px',
    },
    medium: {
      padding: '8px 12px',
      fontSize: '14px',
      minHeight: '36px',
    },
    large: {
      padding: '12px 16px',
      fontSize: '16px',
      minHeight: '44px',
    },
  };

  const inputStyle: React.CSSProperties = {
    ...sizeStyles[size],
    width: fullWidth ? '100%' : 'auto',
    backgroundColor: disabled ? '#5a5a5a' : '#7a7a7a',
    color: disabled ? '#666666' : '#ffffff',
    border: 'none',
    outline: 'none',
    transition: 'background-color 0.2s ease',
    cursor: disabled ? 'not-allowed' : 'text',
    opacity: disabled ? 0.6 : 1,
    ...style,
  };

  const containerStyle: React.CSSProperties = {
    display: 'flex',
    flexDirection: 'column',
    width: fullWidth ? '100%' : 'auto',
  };

  const labelStyle: React.CSSProperties = {
    fontSize: size === 'large' ? '16px' : size === 'medium' ? '14px' : '12px',
    color: '#ffffff',
    marginBottom: '4px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
  };

  const errorStyle: React.CSSProperties = {
    fontSize: '12px',
    color: '#ff6b6b',
    marginTop: '4px',
    fontWeight: 'bold',
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value;
    if (value === undefined) {
      setInternalValue(newValue);
    }
    if (onChange) {
      onChange(newValue);
    }
  };

  const handleFocus = () => {
    setIsFocused(true);
    if (onFocus) {
      onFocus();
    }
  };

  const handleBlur = () => {
    setIsFocused(false);
    if (onBlur) {
      onBlur();
    }
  };

  return (
    <div className={`ui-input-container ${className}`} style={containerStyle}>
      {label && (
        <label className="ui-input-label" style={labelStyle}>
          {label}
          {required && <span style={{ color: '#ff6b6b' }}> *</span>}
        </label>
      )}
      <input
        type={type}
        placeholder={placeholder}
        value={currentValue}
        onChange={handleChange}
        onFocus={handleFocus}
        onBlur={handleBlur}
        disabled={disabled}
        readOnly={readOnly}
        required={required}
        className={`ui-input ui-input-${size}`}
        style={inputStyle}
      />
      {error && (
        <div className="ui-input-error" style={errorStyle}>
          {error}
        </div>
      )}
    </div>
  );
};
