import React, { useState, useEffect } from 'react';
import { Panel, Button, Tab, FloatingButton, Tooltip } from './index';
import { createEnemyFromDefinition } from '../../game/EnemyTypes';

interface DebugPanelProps {
  gameRef: React.RefObject<any>;
  playerStats: any;
  gameStarted: boolean;
  handleSidebarUpgrade: (upgrade: any) => void;
  UPGRADES: any[];
  UPGRADE_CATEGORIES: any;
  UPGRADE_COLORS: any;
  ENEMY_DEFINITIONS: any;
  STAGE_DEFINITIONS: any[];
  getCurrentStage: any;

  EnemyType: any;
  getUpgradeSupplyStatus: () => Record<string, { rarity: number; supply: number }>;
  resetUpgradeSupply: any;
}

// Helper function to convert number to Roman numerals
const toRoman = (num: number): string => {
  const romanNumerals = [
    { value: 1000, numeral: 'M' },
    { value: 900, numeral: 'CM' },
    { value: 500, numeral: 'D' },
    { value: 400, numeral: 'CD' },
    { value: 100, numeral: 'C' },
    { value: 90, numeral: 'XC' },
    { value: 50, numeral: 'L' },
    { value: 40, numeral: 'XL' },
    { value: 10, numeral: 'X' },
    { value: 9, numeral: 'IX' },
    { value: 5, numeral: 'V' },
    { value: 4, numeral: 'IV' },
    { value: 1, numeral: 'I' }
  ];

  let result = '';
  for (const { value, numeral } of romanNumerals) {
    while (num >= value) {
      result += numeral;
      num -= value;
    }
  }
  return result;
};

// UpgradeCard component (copied from App.tsx) - HALF SIZE VERSION
const UpgradeCard = ({ upgrade, onClick, level }: { upgrade: any, onClick?: () => void, level: number }) => {
  const rarity = upgrade.rarity || 1;
  const rarityColors = {
    1: '#ffffff', // White for tier 1
    2: '#ffd700', // Gold for tier 2
    3: '#ff6b6b'  // Red for tier 3
  };
  
  // Calculate font size based on text length to ensure it fits
  const titleText = `${upgrade.name} ${toRoman(level)}`;
  
  // Smaller font sizes for half-size cards
  let fontSize = 0.8; // Base size (reduced from 1.2)
  if (titleText.length > 15) {
    fontSize = 0.7;
  }
  if (titleText.length > 20) {
    fontSize = 0.6;
  }
  if (titleText.length > 25) {
    fontSize = 0.5;
  }
  if (titleText.length > 30) {
    fontSize = 0.45;
  }
  
  return (
    <Tooltip 
      content={upgrade.longdescription}
      position="top"
      upgrade={upgrade}
    >
      <div
        role={onClick ? 'button' : undefined}
        tabIndex={onClick ? 0 : undefined}
        onClick={onClick}
        onKeyDown={onClick ? (e) => { if (e.key === 'Enter' || e.key === ' ') onClick(); } : undefined}
        style={{
          cursor: onClick ? 'pointer' : 'default',
          background: `linear-gradient(15deg, ${upgrade.category === 'Physical' ? '#ff4444' : upgrade.category === 'Magical' ? '#c388f7' : upgrade.category === 'Defensive' ? '#3ecf4a' : '#44aaff'}33 0%, #23232b 100%), #23232b`,
          border: 'none',
          borderRadius: 6,
          marginBottom: '0',
          padding: '0.5rem 0.35rem',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: '0.35rem',
          width: 100,
          height: 140,
          minWidth: 100,
          maxWidth: 100,
          minHeight: 140,
          maxHeight: 140,
          boxSizing: 'border-box',
          position: 'relative',
          overflow: 'hidden',
          justifyContent: 'flex-start',
          boxShadow: '4px 8px 16px 0 #0006',
          outline: 'none',
          transition: 'box-shadow 0.15s, transform 0.15s',
        }}
        onMouseDown={e => e.currentTarget.style.transform = 'scale(0.97)'}
        onMouseUp={e => e.currentTarget.style.transform = ''}
      >
        {/* Rarity stars - centered at top */}
        <div style={{ 
          position: 'absolute', 
          left: '50%', 
          top: 4, 
          transform: 'translateX(-50%)',
          display: 'flex', 
          gap: '1px',
          fontSize: '0.8rem'
        }}>
          {Array.from({ length: rarity }, (_, i) => (
            <span key={i} style={{ color: rarityColors[rarity as keyof typeof rarityColors] }}>
              ⭐
            </span>
          ))}
        </div>
        
        <div style={{ 
          fontWeight: 700, 
          color: upgrade.category === 'Physical' ? '#ff4444' : upgrade.category === 'Magical' ? '#c388f7' : upgrade.category === 'Defensive' ? '#3ecf4a' : '#44aaff', 
          fontSize: `${fontSize}rem`, 
          marginBottom: 0, 
          marginTop: '0.75rem',
          textAlign: 'center',
          width: '100%',
          lineHeight: '1.1',
          height: '1.2rem',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          whiteSpace: 'nowrap',
          paddingLeft: '4px',
          paddingRight: '4px'
        }}>{titleText}</div>
        <div style={{
          fontSize: '0.45rem',
          fontWeight: '700',
          background: upgrade.category === 'Physical' ? '#ff4444' : upgrade.category === 'Magical' ? '#c388f7' : upgrade.category === 'Defensive' ? '#3ecf4a' : '#44aaff',
          color: '#111',
          borderRadius: 2,
          padding: '0.5px 2.5px',
          marginBottom: 2,
          marginTop: 0,
          letterSpacing: '0.02em',
          alignSelf: 'center',
          boxShadow: '0 0.5px 2px #0002',
          border: '0.5px solid #fff2',
          display: 'inline-block',
          height: '0.6rem',
          lineHeight: '0.6rem'
        }}>{upgrade.category}</div>
        <div style={{ 
          fontSize: '1.2rem', 
          height: '1.2rem', 
          display: 'flex', 
          alignItems: 'center', 
          justifyContent: 'center',
          marginBottom: 4
        }}>✨</div>
        <div style={{ 
          fontSize: '0.6rem', 
          color: '#fff', 
          textAlign: 'center', 
          marginTop: 0,
          flex: 1,
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'center',
          paddingLeft: '4px',
          paddingRight: '4px',
          lineHeight: '0.8rem'
        }}>{upgrade.shortdescription}</div>
      </div>
    </Tooltip>
  );
};

const DebugPanel: React.FC<DebugPanelProps> = ({
  gameRef,
  playerStats,
  gameStarted,
  handleSidebarUpgrade,
  UPGRADES,
  UPGRADE_CATEGORIES,
  UPGRADE_COLORS,
  ENEMY_DEFINITIONS,
  STAGE_DEFINITIONS,
  getCurrentStage,
  EnemyType,
  getUpgradeSupplyStatus,
  resetUpgradeSupply
}) => {
  const [debugPanelOpen, setDebugPanelOpen] = useState(false);
  const [activeDebugTab, setActiveDebugTab] = useState<'upgrades' | 'enemies' | 'stages' | 'items' | 'stats' | 'misc' | 'supply'>('enemies');
  const [autoSpawnEnabled, setAutoSpawnEnabled] = useState(true);
  const [showPathingDebug, setShowPathingDebug] = useState(false);

  // Add N key functionality
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'n' || e.key === 'N') {
        setDebugPanelOpen(prev => !prev);
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  // Dynamic debug panel width based on active tab
  const getDebugPanelWidth = () => {
    if (!debugPanelOpen) return 48;
    
    switch (activeDebugTab) {
      case 'upgrades':
        return '40vw';
      case 'enemies':
        return '20vw';
      case 'stages':
        return '35vw';
      case 'stats':
        return '35vw';
      case 'items':
        return '25vw';
      case 'misc':
        return '25vw';
      default:
        return '20vw';
    }
  };

  // Sync auto spawn state with the actual timer state
  const syncAutoSpawnState = () => {
    if (gameRef.current) {
      const scene = gameRef.current.scene.getScene('MainScene') as any;
      if (scene) {
        const spawnDisabled = scene.enemySpawnDisabled;
        if (spawnDisabled !== !autoSpawnEnabled) {
          setAutoSpawnEnabled(!spawnDisabled);
        }
      }
    }
  };

  // Sync state when debug panel opens
  const handleDebugPanelToggle = () => {
    const newOpenState = !debugPanelOpen;
    setDebugPanelOpen(newOpenState);
    
    // Sync auto spawn state when opening debug panel
    if (newOpenState) {
      syncAutoSpawnState();
    }
  };

  // Helper function to format time
  const formatTimeToMMSS = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        height: '100vh',
        width: getDebugPanelWidth(),
        background: debugPanelOpen ? 'rgba(30,30,40,0.3)' : 'none',
        zIndex: 50,
        boxShadow: debugPanelOpen ? '2px 0 16px #000a' : 'none',
        transition: 'width 0.2s',
        overflow: 'hidden',
        display: 'flex',
        flexDirection: 'row',
      }}
    >
      <FloatingButton
        onClick={handleDebugPanelToggle}
        variant="secondary"
        size="medium"
        style={{
          position: 'absolute',
          top: '8px',
          left: debugPanelOpen ? `calc(${getDebugPanelWidth()} - 48px)` : '8px',
          zIndex: 51,
          transition: 'left 0.2s',
        }}
      >
        {debugPanelOpen ? '←' : '→'}
      </FloatingButton>
      
      {debugPanelOpen && (
        <div style={{ display: 'flex', flexDirection: 'row', flex: 1, height: '100vh' }}>
          {/* Tab Navigation */}
          <div style={{ 
            width: 60, 
            backgroundColor: '#5a5a5a',
            display: 'flex', 
            flexDirection: 'column',
            padding: '8px 0',
            alignItems: 'center'
          }}>
            <Tab
              label="Upgrades"
              icon="⚡"
              rotated={true}
              isActive={activeDebugTab === 'upgrades'}
              onClick={() => setActiveDebugTab('upgrades')}
            />
            <Tab
              label="Enemies"
              icon="👹"
              rotated={true}
              isActive={activeDebugTab === 'enemies'}
              onClick={() => setActiveDebugTab('enemies')}
            />
            <Tab
              label="Stages"
              icon="🌍"
              rotated={true}
              isActive={activeDebugTab === 'stages'}
              onClick={() => setActiveDebugTab('stages')}
            />
            <Tab
              label="Items"
              icon="🎒"
              rotated={true}
              isActive={activeDebugTab === 'items'}
              onClick={() => setActiveDebugTab('items')}
            />
            <Tab
              label="Stats"
              icon="📊"
              rotated={true}
              isActive={activeDebugTab === 'stats'}
              onClick={() => setActiveDebugTab('stats')}
            />
            <Tab
              label="Misc"
              icon="⚙️"
              rotated={true}
              isActive={activeDebugTab === 'misc'}
              onClick={() => setActiveDebugTab('misc')}
            />
            <Tab
              label="Supply"
              icon="📦"
              rotated={true}
              isActive={activeDebugTab === 'supply'}
              onClick={() => setActiveDebugTab('supply')}
            />
          </div>
          
          {/* Content Area */}
          <div style={{ 
            flex: 1, 
            padding: '16px',
            backgroundColor: '#7a7a7a',
            overflowY: 'auto'
          }}>
            {debugPanelOpen && (
              <div style={{ 
                fontSize: '10px', 
                color: '#999999', 
                textAlign: 'center', 
                marginBottom: '8px',
                fontFamily: 'monospace'
              }}>
                Panel Width: {getDebugPanelWidth()} | Press N to toggle
              </div>
            )}
            
            {/* Game Status Check */}
            <Panel title="Game Status" variant="secondary" size="small" style={{ marginBottom: '12px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', fontSize: '11px' }}>
                <Button
                  variant="secondary"
                  size="small"
                  onClick={() => {
                    console.log('=== GAME STATUS CHECK ===');
                    console.log('gameRef.current:', !!gameRef.current);
                    if (gameRef.current) {
                      console.log('gameRef.current.scene:', !!gameRef.current.scene);
                      console.log('gameRef.current.scene.scenes:', gameRef.current.scene.scenes);
                      const scene = gameRef.current.scene.getScene('MainScene') as any;
                      console.log('MainScene found:', !!scene);
                      if (scene) {
                        console.log('Scene is running:', scene.scene.isActive());
                        console.log('Player exists:', !!scene.player);
                        console.log('Enemies group exists:', !!scene.enemies);
                        console.log('Game started:', gameStarted);
                        console.log('Player stats:', playerStats);
                      }
                    }
                    console.log('=== END STATUS CHECK ===');
                  }}
                >
                  Check Game Status
                </Button>
              </div>
            </Panel>
            
            {activeDebugTab === 'upgrades' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {/* Physical Upgrades */}
                <Panel
                 title="Physical Upgrades"
                 variant="dark"
                 size="large"
                 fullWidth
                 style={{ borderLeft: `4px solid ${UPGRADE_COLORS.Physical}` }}
               >
                                        <div style={{
                       display: 'grid',
                       gridTemplateColumns: 'repeat(auto-fill, 100px)',
                       gridTemplateRows: 'repeat(auto-fit, 140px)',
                       gap: '4px',
                       justifyContent: 'start',
                       padding: '8px'
                     }}>
                       {UPGRADES.filter(u => u.category === UPGRADE_CATEGORIES.PHYSICAL).map((u) => (
                         <UpgradeCard
                           key={u.name}
                           upgrade={u}
                           level={(playerStats.upgrades as Record<string, number>)?.[u.name] || 0}
                           onClick={() => handleSidebarUpgrade(u)}
                         />
                       ))}
                     </div>
                </Panel>

                {/* Magical Upgrades */}
                <Panel
                 title="Magical Upgrades"
                 variant="dark"
                 size="large"
                 fullWidth
                 style={{ borderLeft: `4px solid ${UPGRADE_COLORS.Magical}` }}
               >
                                        <div style={{
                       display: 'grid',
                       gridTemplateColumns: 'repeat(auto-fill, 100px)',
                       gridTemplateRows: 'repeat(auto-fit, 140px)',
                       gap: '4px',
                       justifyContent: 'start',
                       padding: '8px'
                     }}>
                       {UPGRADES.filter(u => u.category === UPGRADE_CATEGORIES.MAGICAL).map((u) => (
                         <UpgradeCard
                           key={u.name}
                           upgrade={u}
                           level={(playerStats.upgrades as Record<string, number>)?.[u.name] || 0}
                           onClick={() => handleSidebarUpgrade(u)}
                         />
                       ))}
                     </div>
                </Panel>

                {/* Defensive Upgrades */}
                <Panel
                 title="Defensive Upgrades"
                 variant="dark"
                 size="large"
                 fullWidth
                 style={{ borderLeft: `4px solid ${UPGRADE_COLORS.Defensive}` }}
               >
                                        <div style={{
                       display: 'grid',
                       gridTemplateColumns: 'repeat(auto-fill, 100px)',
                       gridTemplateRows: 'repeat(auto-fit, 140px)',
                       gap: '4px',
                       justifyContent: 'start',
                       padding: '8px'
                     }}>
                       {UPGRADES.filter(u => u.category === UPGRADE_CATEGORIES.DEFENSIVE).map((u) => (
                         <UpgradeCard
                           key={u.name}
                           upgrade={u}
                           level={(playerStats.upgrades as Record<string, number>)?.[u.name] || 0}
                           onClick={() => handleSidebarUpgrade(u)}
                         />
                       ))}
                     </div>
                </Panel>

                {/* Utility Upgrades */}
                <Panel
                 title="Utility Upgrades"
                 variant="dark"
                 size="large"
                 fullWidth
                 style={{ borderLeft: `4px solid ${UPGRADE_COLORS.Utility}` }}
               >
                                        <div style={{
                       display: 'grid',
                       gridTemplateColumns: 'repeat(auto-fill, 100px)',
                       gridTemplateRows: 'repeat(auto-fit, 140px)',
                       gap: '4px',
                       justifyContent: 'start',
                       padding: '8px'
                     }}>
                       {UPGRADES.filter(u => u.category === UPGRADE_CATEGORIES.UTILITY).map((u) => (
                         <UpgradeCard
                           key={u.name}
                           upgrade={u}
                           level={(playerStats.upgrades as Record<string, number>)?.[u.name] || 0}
                           onClick={() => handleSidebarUpgrade(u)}
                         />
                       ))}
                     </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'enemies' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <Panel title="Enemy Controls" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            scene.enemySpawnDisabled = !scene.enemySpawnDisabled;
                            setAutoSpawnEnabled(!scene.enemySpawnDisabled);
                            console.log('Auto spawn:', !scene.enemySpawnDisabled ? 'enabled' : 'disabled');
                          }
                        }
                      }}
                    >
                      {autoSpawnEnabled ? 'Disable' : 'Enable'} Auto Spawn
                    </Button>
                    
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene && scene.enemies) {
                            scene.enemies.clear(true, true);
                            console.log('Cleared all enemies');
                          }
                        }
                      }}
                    >
                      Clear All Enemies
                    </Button>
                    
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            setShowPathingDebug(!showPathingDebug);
                            (window as any).__SHOW_PATHING_DEBUG = !showPathingDebug;
                            console.log('Pathing debug:', !showPathingDebug ? 'enabled' : 'disabled');
                          }
                        }
                      }}
                    >
                      {showPathingDebug ? 'Hide' : 'Show'} Pathing Debug
                    </Button>
                    
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            console.log('Spawning test enemies...');
                            for (let i = 0; i < 5; i++) {
                              const x = Math.random() * 800 + 100;
                              const y = Math.random() * 600 + 100;
                              scene.enemySystem.spawnTestEnemy(x, y);
                            }
                          }
                        }
                      }}
                    >
                      Spawn Test Enemies
                    </Button>
                  </div>
                </Panel>
                
                <Panel title="Enemy Types by Stage" variant="dark" size="large" fullWidth>
                  <div style={{ 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', 
                    gap: '12px', 
                    maxHeight: '700px', 
                    overflowY: 'auto',
                    padding: '8px'
                  }}>
                    {/* Generate stages dynamically from STAGE_DEFINITIONS */}
                    {STAGE_DEFINITIONS.map((stage, stageIndex) => (
                      <div key={stageIndex} style={{ 
                        background: '#444', 
                        borderRadius: '6px', 
                        padding: '8px',
                        border: '2px solid #666',
                        minHeight: '200px',
                        display: 'flex',
                        flexDirection: 'column'
                      }}>
                        <div style={{ 
                          fontSize: '14px', 
                          fontWeight: 'bold', 
                          color: '#fff', 
                          marginBottom: '8px',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '8px',
                          flexShrink: 0
                        }}>
                          {stage.emoji} {stage.name}
                        </div>
                        <div style={{ 
                          display: 'grid', 
                          gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', 
                          gap: '4px',
                          flex: 1,
                          overflowY: 'auto'
                        }}>
                          {/* All enemies for this stage in one grid */}
                          {[...stage.normalEnemies, ...stage.specialEnemies, ...stage.bossEnemies].map((enemyKey: string) => {
                            const enemy = ENEMY_DEFINITIONS[enemyKey];
                            if (!enemy) return null;
                            
                            // Determine enemy type for styling
                            const isSpecial = stage.specialEnemies.includes(enemyKey);
                            const isBoss = stage.bossEnemies.includes(enemyKey);
                            
                            return (
                              <Button
                                key={enemyKey}
                                variant="secondary"
                                size="small"
                                onClick={() => {
                                  if (gameRef.current) {
                                    const scene = gameRef.current.scene.getScene('MainScene') as any;
                                    if (scene && scene.enemySystem && scene.player) {
                                      try {
                                        console.log(`Debug: Spawning ${enemy.name} via enemy system`);
                                        
                                        // Get spawn position near player
                                        const spawnX = scene.player.x + (Math.random() - 0.5) * 400 + 200;
                                        const spawnY = scene.player.y + (Math.random() - 0.5) * 400 + 200;
                                        
                                        // Use the enemy system's spawn method but with our specific enemy
                                        scene.enemySystem.spawnSpecificEnemy(enemyKey, spawnX, spawnY);
                                        
                                        console.log('Debug: Enemy spawned successfully');
                                      } catch (error) {
                                        console.error('Debug: Error spawning enemy:', error);
                                      }
                                    } else {
                                      console.error('Debug: Scene, enemySystem, or player not found');
                                    }
                                  } else {
                                    console.error('Debug: gameRef.current is null');
                                  }
                                }}
                                style={{
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: '4px',
                                  justifyContent: 'flex-start',
                                  padding: '4px 6px',
                                  fontSize: '10px',
                                  height: 'auto',
                                  minHeight: '28px',
                                  border: isBoss ? '1px solid #ff4444' : isSpecial ? '1px solid #ffaa00' : 'none'
                                }}
                              >
                                <span style={{ 
                                  width: '8px', 
                                  height: '8px', 
                                  borderRadius: '50%', 
                                  backgroundColor: `#${enemy.color.toString(16).padStart(6, '0')}`,
                                  border: '1px solid #fff',
                                  flexShrink: 0
                                }}></span>
                                <span style={{ 
                                  flex: 1, 
                                  textAlign: 'left', 
                                  overflow: 'hidden', 
                                  textOverflow: 'ellipsis', 
                                  whiteSpace: 'nowrap',
                                  color: isBoss ? '#ff4444' : isSpecial ? '#ffaa00' : '#fff',
                                  fontWeight: isBoss || isSpecial ? 'bold' : 'normal'
                                }}>
                                  {enemy.name}
                                </span>
                              </Button>
                            );
                          })}
                        </div>
                      </div>
                    ))}

                    {/* All Other Enemies (not assigned to any stage) */}
                    <div style={{ 
                      background: '#444', 
                      borderRadius: '6px', 
                      padding: '8px',
                      border: '2px solid #666',
                      minHeight: '200px',
                      display: 'flex',
                      flexDirection: 'column'
                    }}>
                      <div style={{ 
                        fontSize: '14px', 
                        fontWeight: 'bold', 
                        color: '#fff', 
                        marginBottom: '8px',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '8px',
                        flexShrink: 0
                      }}>
                        🎲 Unassigned Enemies
                      </div>
                      <div style={{ 
                        display: 'grid', 
                        gridTemplateColumns: 'repeat(auto-fill, minmax(140px, 1fr))', 
                        gap: '4px',
                        flex: 1,
                        overflowY: 'auto'
                      }}>
                        {Object.entries(ENEMY_DEFINITIONS)
                          .filter(([key, enemy]: [string, any]) => {
                            // Check if this enemy is not assigned to any stage
                            const allStageEnemies = STAGE_DEFINITIONS.flatMap(stage => [
                              ...stage.normalEnemies,
                              ...stage.specialEnemies,
                              ...stage.bossEnemies
                            ]);
                            return !allStageEnemies.includes(key);
                          })
                          .map(([key, enemy]: [string, any]) => (
                            <Button
                              key={key}
                              variant="secondary"
                              size="small"
                              onClick={() => {
                                if (gameRef.current) {
                                  const scene = gameRef.current.scene.getScene('MainScene') as any;
                                                                     if (scene && scene.enemySystem && scene.player) {
                                     try {
                                       console.log(`Debug: Spawning ${enemy.name} via enemy system`);
                                       
                                       // Get spawn position near player
                                       const spawnX = scene.player.x + (Math.random() - 0.5) * 400 + 200;
                                       const spawnY = scene.player.y + (Math.random() - 0.5) * 400 + 200;
                                       
                                       // Use the enemy system's spawn method but with our specific enemy
                                       scene.enemySystem.spawnSpecificEnemy(key, spawnX, spawnY);
                                       
                                       console.log('Debug: Enemy spawned successfully');
                                     } catch (error) {
                                       console.error('Debug: Error spawning enemy:', error);
                                     }
                                   } else {
                                     console.error('Debug: Scene, enemySystem, or player not found');
                                   }
                                } else {
                                  console.error('Debug: gameRef.current is null');
                                }
                              }}
                              style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: '4px',
                                justifyContent: 'flex-start',
                                padding: '4px 6px',
                                fontSize: '10px',
                                height: 'auto',
                                minHeight: '28px'
                              }}
                            >
                              <span style={{ 
                                width: '8px', 
                                height: '8px', 
                                borderRadius: '50%', 
                                backgroundColor: `#${enemy.color.toString(16).padStart(6, '0')}`,
                                border: '1px solid #fff',
                                flexShrink: 0
                              }}></span>
                              <span style={{ flex: 1, textAlign: 'left', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                {enemy.name}
                              </span>
                            </Button>
                          ))}
                      </div>
                    </div>
                  </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'stages' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <Panel title="Stage Controls" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            const elapsed = Math.floor(scene.gameElapsedTime / 1000);
                            const currentStage = getCurrentStage(elapsed);
                            if (currentStage) {
                              const currentStageIndex = STAGE_DEFINITIONS.findIndex((stage: any) => stage.name === currentStage.name);
                              const nextStageIndex = currentStageIndex + 1;
                              if (nextStageIndex < STAGE_DEFINITIONS.length) {
                                const nextStage = STAGE_DEFINITIONS[nextStageIndex];
                                // Set timer to 1 second before next stage begins
                                scene.gameElapsedTime = (nextStage.startTime - 1) * 1000;
                                console.log(`Skipped to stage ${nextStageIndex + 1}: ${nextStage.name}`);
                              } else {
                                console.log('Already at the last stage');
                              }
                            }
                          }
                        }
                      }}
                    >
                      Skip Stage
                    </Button>
                  </div>
                </Panel>
                
                <Panel title="Current Stage Info" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    {(() => {
                      const elapsed = playerStats.timer / 1000;
                      const currentStage = getCurrentStage(elapsed);
                      return currentStage ? (
                        <>
                          <div style={{ fontSize: '14px', fontWeight: 'bold', color: '#fff' }}>
                            {currentStage.name}
                          </div>
                          <div style={{ fontSize: '12px', color: '#ccc' }}>
                            Duration: {currentStage.endTime - currentStage.startTime}s
                          </div>
                          <div style={{ fontSize: '12px', color: '#ccc' }}>
                            Background: {currentStage.backgroundColor}
                          </div>
                        </>
                      ) : (
                        <div style={{ fontSize: '12px', color: '#ccc' }}>No stage info available</div>
                      );
                    })()}
                  </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'stats' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <Panel title="Player Statistics" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '12px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Level:</span>
                      <span style={{ color: '#44aaff' }}>{playerStats.level}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>XP:</span>
                      <span style={{ color: '#44aaff' }}>{playerStats.xp} / {playerStats.xpToNext}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Health:</span>
                      <span style={{ color: '#ff4444' }}>{playerStats.hp} / {playerStats.maxHp}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Armor:</span>
                      <span style={{ color: '#3ecf4a' }}>{playerStats.armor}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Gold:</span>
                      <span style={{ color: '#ffd700' }}>{playerStats.gold}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Time Survived:</span>
                      <span style={{ color: '#fff' }}>{Math.floor(playerStats.timer / 1000)}s</span>
                    </div>
                  </div>
                </Panel>
                
                <Panel title="Combat Statistics" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '12px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Enemies Killed:</span>
                      <span style={{ color: '#ff4444' }}>{playerStats.enemiesKilled || 0}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Damage Dealt:</span>
                      <span style={{ color: '#ffaa00' }}>{playerStats.totalDamageDealt || 0}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Damage Taken:</span>
                      <span style={{ color: '#ff6666' }}>{playerStats.totalDamageTaken || 0}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Shots Fired:</span>
                      <span style={{ color: '#44aaff' }}>{playerStats.shotsFired || 0}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Shots Hit:</span>
                      <span style={{ color: '#3ecf4a' }}>{playerStats.shotsHit || 0}</span>
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Accuracy:</span>
                      <span style={{ color: '#fff' }}>
                        {playerStats.shotsFired && playerStats.shotsHit ? 
                          `${((playerStats.shotsHit / playerStats.shotsFired) * 100).toFixed(1)}%` : 
                          '0%'
                        }
                      </span>
                    </div>
                  </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'items' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {/* Player Items */}
                <Panel title="Player Items" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    <div style={{ fontSize: '12px', color: '#ccc', marginBottom: '4px' }}>
                      Current items: {(() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene && scene.itemManager) {
                            const items = scene.itemManager.getPlayerItems();
                            return items.length > 0 ? items.join(', ') : 'None';
                          }
                        }
                        return 'No game data';
                      })()}
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Health Booster');
                            }
                          }
                        }}
                      >
                        Give Health Booster
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Regeneration Stone');
                            }
                          }
                        }}
                      >
                        Give Regeneration Stone
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Shotgun');
                            }
                          }
                        }}
                      >
                        Give Shotgun
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Dual Berettas');
                            }
                          }
                        }}
                      >
                        Give Dual Berettas
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Monocule');
                            }
                          }
                        }}
                      >
                        Give Monocule
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Haste Shard');
                            }
                          }
                        }}
                      >
                        Give Haste Shard
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('HE Grenade');
                            }
                          }
                        }}
                      >
                        Give HE Grenade
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Echo Stone');
                            }
                          }
                        }}
                      >
                        Give Echo Stone
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Magnifying Stone');
                            }
                          }
                        }}
                      >
                        Give Magnifying Stone
                      </Button>

                      <Button
                        variant="secondary"
                        size="small"
                        onClick={() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              scene.itemManager.giveItemToPlayer('Health Potion');
                            }
                          }
                        }}
                      >
                        Give Health Potion
                      </Button>
                    </div>
                  </div>
                </Panel>

                {/* Item Effects Testing */}
                <Panel title="Item Effects Testing" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene && scene.itemManager) {
                            scene.itemManager.createGrenadeExplosion(
                              scene.player.x + 100,
                              scene.player.y,
                              100
                            );
                          }
                        }
                      }}
                    >
                      Test Grenade Explosion
                    </Button>

                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene && scene.itemManager) {
                            // Damage player to test health potion
                            if (scene.playerCharacter) {
                              const currentHp = scene.playerCharacter.hp;
                              const damageAmount = Math.floor(currentHp * 0.6); // Damage to 40% HP
                              scene.playerCharacter.takeDamage(damageAmount);
                            }
                          }
                        }
                      }}
                    >
                      Damage Player (Test Health Potion)
                    </Button>

                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene && scene.playerCharacter) {
                            scene.playerCharacter.gold += 1000;
                            console.log('Added 1000 gold to player');
                          }
                        }
                      }}
                    >
                      Add 1000 Gold
                    </Button>
                  </div>
                </Panel>

                {/* Item Statistics */}
                <Panel title="Item Statistics" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '12px' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Items Owned:</span>
                      <span style={{ color: '#44aaff' }}>
                        {(() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              return scene.itemManager.getPlayerItems().length;
                            }
                          }
                          return 0;
                        })()}
                      </span>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Player Gold:</span>
                      <span style={{ color: '#ffd700' }}>
                        {(() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.playerCharacter) {
                              return scene.playerCharacter.gold;
                            }
                          }
                          return 0;
                        })()}
                      </span>
                    </div>

                    <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>Health Potion Active:</span>
                      <span style={{ color: '#ff4444' }}>
                        {(() => {
                          if (gameRef.current) {
                            const scene = gameRef.current.scene.getScene('MainScene') as any;
                            if (scene && scene.itemManager) {
                              return 'No'; // This would need to be tracked in ItemManager
                            }
                          }
                          return 'Unknown';
                        })()}
                      </span>
                    </div>
                  </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'misc' && (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <Panel title="Misc Controls" variant="dark" size="large" fullWidth>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            const elapsed = Math.floor(scene.gameElapsedTime / 1000);
                            const currentStage = getCurrentStage(elapsed);
                            if (currentStage) {
                              const currentStageIndex = STAGE_DEFINITIONS.findIndex((stage: any) => stage.name === currentStage.name);
                              const nextStageIndex = currentStageIndex + 1;
                              if (nextStageIndex < STAGE_DEFINITIONS.length) {
                                const nextStage = STAGE_DEFINITIONS[nextStageIndex];
                                // Set timer to 1 second before next stage begins
                                scene.gameElapsedTime = (nextStage.startTime - 1) * 1000;
                                console.log(`Skipped to stage ${nextStageIndex + 1}: ${nextStage.name}`);
                              } else {
                                console.log('Already at the last stage');
                              }
                            }
                          }
                        }
                      }}
                    >
                      Skip Stage
                    </Button>
                    
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            console.log('Spawning test crab_scuttler with proper definition');
                            // Use the proper enemy definition system
                            const enemyDef = ENEMY_DEFINITIONS['crab_scuttler'];
                            if (enemyDef) {
                              const enemyData = createEnemyFromDefinition(enemyDef, 0, 'crab_scuttler');
                              console.log('Created enemy:', enemyData.type);
                              // Spawn the enemy at player position for testing
                              if (scene.player) {
                                const enemy = scene.add.circle(
                                  scene.player.x + 200, 
                                  scene.player.y + 200, 
                                  enemyDef.radius, 
                                  enemyDef.color
                                );
                                // Copy enemy data to the sprite
                                Object.assign(enemy, enemyData);
                                scene.enemies?.add(enemy);
                                console.log('Enemy spawned: crab_scuttler');
                              }
                            }
                          }
                        }
                      }}
                    >
                      Spawn Test Enemy
                    </Button>
                    
                    <Button
                      variant="secondary"
                      size="small"
                      onClick={() => {
                        if (gameRef.current) {
                          const scene = gameRef.current.scene.getScene('MainScene') as any;
                          if (scene) {
                            console.log('Creating test gold pickup near player');
                            scene.createGoldPickup(scene.player.x + 100, scene.player.y + 100, 5, false);
                          }
                        }
                      }}
                    >
                      Create Test Gold
                    </Button>
                  </div>
                </Panel>
                
                <Panel title="Enemy Scaling Info" variant="secondary" size="small">
                  <div style={{ display: 'flex', flexDirection: 'column', gap: '4px', fontSize: '11px' }}>
                    {(() => {
                      const elapsed = playerStats.timer / 1000;
                      const currentStage = getCurrentStage(elapsed);

                      return (
                        <>
                          <span>Current Stage: {currentStage ? currentStage.name : 'Unknown'}</span>
                          <span>Elapsed Time: {Math.floor(elapsed / 60)}:{(elapsed % 60).toFixed(0).padStart(2, '0')}</span>
                          <div style={{ marginTop: '4px', paddingTop: '4px', borderTop: '1px solid #444' }}>
                            <span style={{ color: '#cccccc' }}>Scaling: Removed</span>
                            <span style={{ color: '#ffaa00' }}>Stats: Baked-in</span>
                            <span style={{ color: '#ff4444' }}>No Procedural Scaling</span>
                          </div>
                        </>
                      );
                    })()}
                  </div>
                </Panel>
              </div>
            )}
            
            {activeDebugTab === 'supply' && (
              <Panel title="Upgrade Supply Status" variant="dark" size="large" fullWidth>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                  <Panel title="Supply Overview" variant="secondary" size="small">
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                      <span>Total Upgrades: {UPGRADES.length}</span>
                      <span>Tier 1 (7 supply): {UPGRADES.filter(u => u.rarity === 1).length} upgrades</span>
                      <span>Tier 2 (5 supply): {UPGRADES.filter(u => u.rarity === 2).length} upgrades</span>
                      <span>Tier 3 (3 supply): {UPGRADES.filter(u => u.rarity === 3).length} upgrades</span>
                    </div>
                  </Panel>
                  
                  <Panel title="Current Supply" variant="secondary" size="small">
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', maxHeight: '400px', overflowY: 'auto' }}>
                      {(() => {
                        const supplyStatus = getUpgradeSupplyStatus();
                        const rarityColors = { 1: '#ffffff', 2: '#ffd700', 3: '#ff6b6b' };
                        
                        return Object.entries(supplyStatus)
                          .sort((a, b) => (a[1] as any).rarity - (b[1] as any).rarity || a[0].localeCompare(b[0]))
                          .map(([name, status]: [string, any]) => (
                            <div key={name} style={{ 
                              display: 'flex', 
                              justifyContent: 'space-between', 
                              alignItems: 'center',
                              padding: '4px 8px',
                              background: '#333',
                              borderRadius: '4px',
                              fontSize: '12px'
                            }}>
                              <span style={{ color: rarityColors[status.rarity as keyof typeof rarityColors] }}>
                                {name} {'⭐'.repeat(status.rarity)}
                              </span>
                              <span style={{ 
                                color: status.supply > 0 ? '#3ecf4a' : '#ff4444',
                                fontWeight: 'bold'
                              }}>
                                {status.supply}
                              </span>
                            </div>
                          ));
                      })()}
                    </div>
                  </Panel>
                  
                  <Button
                    variant="secondary"
                    size="small"
                    onClick={() => {
                      resetUpgradeSupply();
                      console.log('Upgrade supply reset');
                    }}
                  >
                    Reset Supply
                  </Button>
                </div>
              </Panel>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default DebugPanel;
