  // Spawn a new merchant from the green ellipse
  spawnMerchant() {
    // Don't spawn if game is paused or no player exists
    if (this.isPaused) {
      console.log('Cannot spawn merchant: game is paused');
      return;
    }
    if (!this.player) {
      console.log('Cannot spawn merchant: no player found');
      return;
    }

    console.log('🎪 Spawning new merchant...');

    // Get camera for ellipse calculations
    const camera = this.cameras.main;
    const centerX = camera.scrollX + camera.width / 2;
    const centerY = camera.scrollY + camera.height / 2;
    const greenRadiusX = camera.width / Math.sqrt(2);
    const greenRadiusY = camera.height / Math.sqrt(2);

    // Spawn inside green ellipse (not on boundary) at random angle
    const spawnAngle = Math.random() * 2 * Math.PI;
    // Spawn at 80% of green ellipse radius to ensure we're well inside
    const spawnDistance = 0.8;
    const merchantX = centerX + greenRadiusX * Math.cos(spawnAngle) * spawnDistance;
    const merchantY = centerY + greenRadiusY * Math.sin(spawnAngle) * spawnDistance;

    // Create new merchant
    this.merchant = new Merchant(this, merchantX, merchantY);

    // Start merchant movement towards player (200px away)
    this.merchant.startApproach(this.player.x, this.player.y);

    console.log(`✅ Merchant successfully spawned at (${merchantX.toFixed(1)}, ${merchantY.toFixed(1)}) - 30 seconds before stage ${STAGES[this.currentStage].name} ends`);
    console.log(`Merchant object:`, this.merchant);
  }

  // Helper method to desaturate a color (simplified approach)
  desaturateColor(color: number, desaturationFactor: number): number {
    // Extract RGB components from hex color
    const r = (color >> 16) & 0xFF;
    const g = (color >> 8) & 0xFF;
    const b = color & 0xFF;

    // Calculate grayscale value
    const gray = Math.round(0.299 * r + 0.587 * g + 0.114 * b);

    // Blend original color with grayscale based on desaturation factor
    const newR = Math.round(r * (1 - desaturationFactor) + gray * desaturationFactor);
    const newG = Math.round(g * (1 - desaturationFactor) + gray * desaturationFactor);
    const newB = Math.round(b * (1 - desaturationFactor) + gray * desaturationFactor);

    // Return as hex color
    return (newR << 16) | (newG << 8) | newB;
  }

