  // Generalized pausing system
  pauseGame(reason: string) {
    if (this.isPaused) {
      console.log(`Game already paused for: ${this.pauseReason}`);
      return;
    }

    console.log(`Pausing game for: ${reason}`);
    this.isPaused = true;
    this.pauseReason = reason;
    this.pauseStartTime = this.time.now;

    // Pause all game timers
    this.pauseAllTimers();

    // Pause the scene
    this.scene.pause();
  }

  unpauseGame() {
    if (!this.isPaused) {
      console.log('Game is not paused');
      return;
    }

    console.log(`Unpausing game from: ${this.pauseReason}`);

    // Track total paused time
    if (this.pauseStartTime) {
      this.totalPausedTime += (this.time.now - this.pauseStartTime);
      this.pauseStartTime = 0;
    }

    // Clear pause state
    this.isPaused = false;
    this.pauseReason = null;

    // Resume all timers
    this.resumeAllTimers();

    // Start smooth acceleration
    this.startSmoothUnpause();

    // Resume the scene
    this.scene.resume();
  }

  pauseAllTimers() {
    this.pausedTimers.clear();

    // Pause all known timers and store their references
    const timers: Array<{ name: string; timer: Phaser.Time.TimerEvent | undefined; }> = [
      { name: 'enemySpawnTimer', timer: this.enemySpawnTimer },
      { name: 'shootTimer', timer: this.shootTimer },
      { name: 'meteorTimer', timer: this.meteorTimer },
      { name: 'earthShockTimer', timer: this.earthShockTimer },
      { name: 'discoballTimer', timer: this.discoballTimer },
      { name: 'minigameSpawnTimer', timer: this.minigameSpawnTimer }
    ];

    timers.forEach(({ name, timer }) => {
      if (timer) {
        this.pausedTimers.set(name, timer);
        timer.paused = true;
        console.log(`Paused timer: ${name}`);
      }
    });

    // Note: Cooldown timers (lavaShotCooldown, iceShardCooldown) are numbers, not TimerEvents
    // They are handled by the update loop and will naturally pause when the game is paused
  }

  resumeAllTimers() {
    // Resume all paused timers
    this.pausedTimers.forEach((timer, name) => {
      if (timer && typeof timer.paused !== 'undefined') {
        timer.paused = false;
        console.log(`Resumed timer: ${name}`);
      }
    });

    this.pausedTimers.clear();
  }

