import Phaser from 'phaser';

export class Merchant extends Phaser.GameObjects.Container {
  private merchantBox: Phaser.GameObjects.Rectangle;
  private shopInterface?: Phaser.GameObjects.Container;
  private isShopOpen: boolean = false;
  private sceneRef: any;

  // Movement properties
  private targetX: number = 0;
  private targetY: number = 0;
  private moveSpeed: number = 100;
  private baseMoveSpeed: number = 100;
  private isMoving: boolean = false;
  private isWaiting: boolean = false;
  private isLeaving: boolean = false; // New state for continuous movement
  private leaveDirection: { x: number, y: number } = { x: 0, y: 0 }; // Direction for leaving
  private acceleration: number = 1.01; // Speed multiplier per frame
  private waitTimer: Phaser.Time.TimerEvent | null = null;
  private spawnTime: number = 0; // Track when merchant was spawned
  private despawnGracePeriod: number = 2000; // 2 seconds before checking for red ellipse

  constructor(scene: any, x: number, y: number) {
    super(scene, x, y);
    this.sceneRef = scene;
    this.spawnTime = scene.time.now; // Record spawn time
    console.log('Creating merchant at position:', x, y);

    // Create a simple orange box
    this.merchantBox = scene.add.rectangle(0, 0, 40, 40, 0xFF6600); // Orange box
    this.merchantBox.setStrokeStyle(2, 0xCC5500); // Darker orange border

    // Make sure the merchant is visible and has proper depth
    this.setDepth(10);
    this.merchantBox.setDepth(11);

    console.log('Merchant box created and visible');

    // Add to container
    this.add(this.merchantBox);

    // Add to scene
    scene.add.existing(this);

    // Enable physics and set up collision
    if (scene.physics && scene.physics.world) {
      scene.physics.add.existing(this);
      const body = this.body as Phaser.Physics.Arcade.Body;
      body.setImmovable(true);
      body.setCircle(25); // Slightly larger collision circle

      // Add collision with player
      if (scene.player) {
        scene.physics.add.collider(scene.player, this, this.onPlayerTouch, null, this);
        console.log('Merchant collision set up at position:', this.x, this.y);
      }
    } else {
      console.error('Physics world not available for merchant');
    }
  }

  private onPlayerTouch(player: any, merchant: Merchant): void {
    console.log('🎉 COLLISION DETECTED: Player collided with merchant!');
    console.log('Player position:', player.x, player.y);
    console.log('Merchant position:', merchant.x, merchant.y);
    console.log('Distance:', Phaser.Math.Distance.Between(player.x, player.y, merchant.x, merchant.y));

    if (!this.isShopOpen) {
      console.log('Opening merchant shop...');
      this.openShop();
    } else {
      console.log('Merchant shop already open');
    }
  }

  private openShop(): void {
    if (this.isShopOpen) return;

    this.isShopOpen = true;

    // Pause the game using the proper pausing system
    this.sceneRef.pauseGame('merchant');

    console.log('Merchant shop opened');
  }

  private closeShop(): void {
    if (!this.isShopOpen) return;

    this.isShopOpen = false;

    // Resume the game
    this.sceneRef.unpauseGame();

    // Start leaving when shop closes
    this.startLeaving();

    console.log('Merchant shop closed - merchant starting to leave');
  }



  // Start merchant movement towards player (200px away)
  startApproach(playerX: number, playerY: number): void {
    // Calculate direction away from player
    const dx = this.x - playerX;
    const dy = this.y - playerY;
    const distance = Math.sqrt(dx * dx + dy * dy);

    // If too close to player, normalize direction
    if (distance < 200) {
      const normalizedX = dx / distance;
      const normalizedY = dy / distance;
      this.targetX = playerX + normalizedX * 200;
      this.targetY = playerY + normalizedY * 200;
    } else {
      // Already far enough, move to a point 200px from player in current direction
      const normalizedX = dx / distance;
      const normalizedY = dy / distance;
      this.targetX = playerX + normalizedX * 200;
      this.targetY = playerY + normalizedY * 200;
    }

    this.isMoving = true;
    console.log('Merchant approaching target:', this.targetX, this.targetY);
  }

  // Start the 10-second wait timer
  startWaiting(): void {
    this.isMoving = false;
    this.isWaiting = true;

    console.log('Merchant starting to wait for 10 seconds');

    this.waitTimer = this.sceneRef.time.delayedCall(10000, () => {
      this.startMovingAway();
    });
  }

  // Start leaving with continuous accelerating movement
  startLeaving(): void {
    console.log('🏃‍♂️ Merchant starting to leave with continuous movement!');

    // Choose a random direction (not necessarily away from player)
    const angle = Math.random() * 2 * Math.PI;
    this.leaveDirection.x = Math.cos(angle);
    this.leaveDirection.y = Math.sin(angle);

    // Reset speed to base
    this.moveSpeed = this.baseMoveSpeed;

    this.isMoving = false; // Don't use target-based movement
    this.isWaiting = false;
    this.isLeaving = true;
  }

  // Move away from player in a different direction (legacy method - now uses startLeaving)
  startMovingAway(): void {
    this.startLeaving();
  }

  // Check if merchant should despawn (same logic as enemy teleporter)
  checkDespawnCollision(): boolean {
    const camera = this.sceneRef.cameras.main;
    const centerX = camera.scrollX + camera.width / 2;
    const centerY = camera.scrollY + camera.height / 2;

    // Calculate red ellipse parameters (teleporter zone)
    const redRadiusX = camera.width / Math.sqrt(2) * 1.2;
    const redRadiusY = camera.height / Math.sqrt(2) * 1.2;

    // Calculate green ellipse parameters (safe zone)
    const greenRadiusX = camera.width / Math.sqrt(2);
    const greenRadiusY = camera.height / Math.sqrt(2);

    const dx = this.x - centerX;
    const dy = this.y - centerY;

    // Check if inside red ellipse
    const redNormalizedX = dx / redRadiusX;
    const redNormalizedY = dy / redRadiusY;
    const isInsideRed = redNormalizedX * redNormalizedX + redNormalizedY * redNormalizedY <= 1;

    // Check if inside green ellipse
    const greenNormalizedX = dx / greenRadiusX;
    const greenNormalizedY = dy / greenRadiusY;
    const isInsideGreen = greenNormalizedX * greenNormalizedX + greenNormalizedY * greenNormalizedY <= 1;

    // Only despawn if inside red ellipse but significantly outside green ellipse
    const greenDistance = greenNormalizedX * greenNormalizedX + greenNormalizedY * greenNormalizedY;
    const isOutsideGreen = greenDistance > 1.1; // Must be at least 10% outside green ellipse

    const shouldDespawn = isInsideRed && isOutsideGreen;

    // Debug logging for despawn check
    if (shouldDespawn) {
      console.log(`🛑 Merchant despawn check: pos(${this.x.toFixed(1)}, ${this.y.toFixed(1)})`);
      console.log(`   Red distance: ${(redNormalizedX * redNormalizedX + redNormalizedY * redNormalizedY).toFixed(3)}, Inside red: ${isInsideRed}`);
      console.log(`   Green distance: ${greenDistance.toFixed(3)}, Outside green: ${isOutsideGreen}`);
    }

    return shouldDespawn;
  }

  update(): void {
    if (this.isLeaving) {
      // Continuous accelerating movement in fixed direction
      const moveX = this.leaveDirection.x * this.moveSpeed * (1/60); // 60 FPS
      const moveY = this.leaveDirection.y * this.moveSpeed * (1/60);

      this.x += moveX;
      this.y += moveY;

      // Accelerate continuously
      this.moveSpeed *= this.acceleration;

      // Log only every 2 seconds to reduce spam
      if (Math.floor(this.sceneRef.time.now / 2000) % 2 === 0) {
        console.log(`🏃‍♂️ Merchant leaving: speed=${this.moveSpeed.toFixed(1)}, pos(${this.x.toFixed(1)}, ${this.y.toFixed(1)})`);
      }

    } else if (this.isMoving) {
      // Move towards target
      const dx = this.targetX - this.x;
      const dy = this.targetY - this.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > 5) { // Close enough to target
        const moveX = (dx / distance) * this.moveSpeed * (1/60); // 60 FPS
        const moveY = (dy / distance) * this.moveSpeed * (1/60);

        this.x += moveX;
        this.y += moveY;
      } else {
        // Reached target
        this.isMoving = false;
        if (!this.isWaiting) {
          this.startWaiting();
        }
      }
    }

    // Check for despawn collision (same as enemy teleporter) - only after grace period
    const timeSinceSpawn = this.sceneRef.time.now - this.spawnTime;
    if (timeSinceSpawn > this.despawnGracePeriod) {
      const shouldDespawn = this.checkDespawnCollision();
      if (shouldDespawn) {
        console.log(`Merchant reached despawn zone after ${timeSinceSpawn}ms, despawning`);
        this.destroy();
      }
    }
  }

  destroy(): void {
    // Clean up timer if it exists
    if (this.waitTimer) {
      this.waitTimer.remove();
      this.waitTimer = null;
    }
    super.destroy();
  }
}
